package com.termux.app.workspace;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;
import com.termux.app.TermuxActivity;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.ShadowAlertDialog;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class WorkspaceX11DiagnosticsTest {
 private TextView find(View v,String text){if(v instanceof TextView&&text.contentEquals(((TextView)v).getText()))return (TextView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){TextView r=find(((ViewGroup)v).getChildAt(i),text);if(r!=null)return r;}return null;}
 @Test public void allLocalEnvironmentsButNotAgentsOrAiUbuntuHaveX11(){for(String alias:new String[]{"","ubuntu","debian","alpine","fedora","opensuse","void","archlinux"}){WorkspaceStore.Session p=new WorkspaceStore.Session();p.environment="termux";p.prootAlias=alias;assertTrue(WorkspaceDesktops.diagnosticsEligible(p));}WorkspaceStore.Session p=new WorkspaceStore.Session();p.environment="ubuntu";p.prootAlias="ubuntu-ai";assertFalse(WorkspaceDesktops.diagnosticsEligible(p));p.prootAlias="";p.aiAgent="opencode";assertFalse(WorkspaceDesktops.diagnosticsEligible(p));p.aiAgent="";p.environment="codex";assertFalse(WorkspaceDesktops.diagnosticsEligible(p));}
 @Test public void x11DisablesModesAndKeepsExportWithoutChangingMode(){TermuxActivity a=Robolectric.buildActivity(TermuxActivity.class).get();WorkspaceLanguage.select(a,"en");WorkspaceStore.Session p=new WorkspaceStore.Session();p.environment="ubuntu";WorkspaceDiagnostics.register(p,true);WorkspaceDiagnosticsUi.show(a,p,()->null,()->"X11 test state",Runnable::run);AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();View root=d.getWindow().getDecorView();assertNotNull(find(root,"X11"));find(root,"X11").performClick();assertFalse(find(root,"Normal").isEnabled());assertFalse(find(root,"Detailed").isEnabled());assertNotNull(find(root,"X11 test state"));assertNotNull(find(root,"To Download"));assertNotNull(find(root,"Copy report"));assertFalse(WorkspaceDiagnostics.extended(p.id));find(root,"Overview").performClick();assertTrue(find(root,"Detailed").isEnabled());find(root,"Detailed").performClick();assertTrue(WorkspaceDiagnostics.extended(p.id));d.dismiss();}
 @Test public void diagnosticsForSupportedDesktopNeverCreateOrBindIt()throws Exception{TermuxActivity a=Robolectric.buildActivity(TermuxActivity.class).get();WorkspaceLanguage.select(a,"en");WorkspaceStore.Session p=new WorkspaceStore.Session();p.environment="termux";p.prootAlias="opensuse";WorkspaceDesktops desks=new WorkspaceDesktops(a,()->p,()->false,new View(a),()->{},()->{});try{assertTrue(desks.diagnostics(p).contains("No startup snapshot"));boolean[] called={false};desks.prepareDiagnostics(p,()->called[0]=true);assertTrue(called[0]);java.lang.reflect.Field f=WorkspaceDesktops.class.getDeclaredField("channels");f.setAccessible(true);assertTrue(((java.util.Map)f.get(desks)).isEmpty());}finally{desks.close();}}
}
